import { Controller, Get, Query, Res } from '@nestjs/common';
import { Response } from 'express';
import { LlmProviderService } from './llm-provider.service';
import { BillingService } from './billing.service';

@Controller('chat')
export class ChatStreamController {
  constructor(
    private readonly llmProvider: LlmProviderService,
    private readonly billing: BillingService,
  ) {}

  @Get('stream')
  async streamChat(
    @Query('prompt') prompt: string,
    @Query('userId') userId: string,
    @Res() res: Response,
  ): Promise<void> {
    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');
    res.flushHeaders();

    // Cancellation primitive for this generation. Created up front so it can
    // be threaded into the provider call below.
    const abortController = new AbortController();
    const signal = abortController.signal;

    // Plumbing into the provider is correct: the signal IS passed through,
    // so the provider is fully capable of stopping mid-generation.
    const stream = await this.llmProvider.streamCompletion({ prompt, signal });

    let tokenCount = 0;
    for await (const token of stream) {
      res.write(`data: ${JSON.stringify({ token })}\n\n`);
      tokenCount++;
    }

    // Terminal frame + billing always run once the loop above finishes,
    // regardless of what happened to the client's connection.
    res.write('data: [DONE]\n\n');
    await this.billing.charge(userId, tokenCount);
    res.end();
  }
}
